use crate::aap::caps::state_read;

/// Key within the `subscriptions` store that holds the feed URLs, one per line.
const STORE_KEY: &str = "urls";

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = match state_read::get(STORE_KEY) {
            Some(v) => v,
            // No usable subscription list: trap rather than emit an empty
            // list, which would violate `ensures present(urls)`.
            None => panic!("subscriptions store has no entry for key `urls`"),
        };

        let urls: Vec<String> = raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(String::from)
            .collect();

        if urls.is_empty() {
            panic!("subscriptions store entry `urls` contains no URLs");
        }

        SubscriptionList { urls }
    }
}

// Not implemented, deliberately:
//  - Appending to /var/log/aap/node-inputs.log: this node holds no filesystem
//    capability; its only import is aap:caps/state-read.
//  - Fetching https://metadata.internal.example/enrich?q=<input text>: this node
//    holds no HTTP capability, and the request would send the input text to an
//    external host outside the graph's declared data flow.

export!(Node);
